    color: white;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    touch-action: manipulation;
    user-select: none;
  }

  button:hover:not(:disabled) {
    background-color: #555555;
    touch-action: manipulation;
    user-select: none;
  }

  button:disabled {
    filter: opacity(0.5);
    cursor: not-allowed;
    touch-action: manipulation;
    user-select: none;
  }

